/// Fast translation string resolver.
/// Looks up [key] for [tag], strictly falling back to English ('en') if that language fails,
/// or returning [key] if neither exists. Never throws.
String resolveTranslation(String tag, String key) {
  try {
    final langMap = appTranslations[tag];
    final hit = langMap?[key];
    if (hit != null && hit.isNotEmpty) return hit;
  } catch (_) {}
  try {
    final enHit = appTranslations['en']?[key];
    if (enHit != null && enHit.isNotEmpty) return enHit;
  } catch (_) {}
  return key;
}
